# ---------------------------------------------------------------- ridge
L("regresi-ridge",
  [(r"Ridge melalui dekomposisi nilai singular",
    [r"Dengan dekomposisi \(\mathbf{X}=\mathbf{U}\mathbf{D}\mathbf{V}^\top\), prediksi ridge adalah jumlah komponen \(\mathbf{u}_j\) yang masing-masing dikalikan faktor penyusutan \(d_j^2/(d_j^2+\lambda)\). Arah dengan nilai singular kecil, yaitu arah tempat prediktor hampir kolinear dan taksiran OLS paling tidak stabil, disusutkan paling kuat. Arah dengan nilai singular besar hampir tidak berubah.",
     r"Inilah alasan ridge menstabilkan koefisien yang dikacaukan multikolinearitas tanpa membuang variabel mana pun."],
    [r"\mathbf{X}\hat{\boldsymbol{\beta}}^{R}=\sum_j\mathbf{u}_j\,\frac{d_j^2}{d_j^2+\lambda}\,\mathbf{u}_j^\top\mathbf{y},\qquad \hat{\boldsymbol{\beta}}^{R}=\mathbf{V}\operatorname{diag}\Big(\frac{d_j}{d_j^2+\lambda}\Big)\mathbf{U}^\top\mathbf{y}"]),
   (r"Bentuk berkendala dan tafsir Bayes",
    [r"Ridge setara dengan meminimumkan jumlah kuadrat galat dengan kendala \(\sum\beta_j^2\le s\); setiap \(\lambda\) bersesuaian dengan satu \(s\). Dari sisi Bayes, ridge adalah taksiran modus posterior bila setiap \(\beta_j\) diberi sebaran awal normal bermean nol dengan ragam \(\sigma^2/\lambda\): makin besar \(\lambda\), makin kuat keyakinan awal bahwa koefisien kecil."],
    [r"\min_{\boldsymbol{\beta}}\ \|\mathbf{y}-\mathbf{X}\boldsymbol{\beta}\|^2\ \ \text{dengan}\ \ \sum_j\beta_j^2\le s\qquad\Longleftrightarrow\qquad \beta_j\sim N\big(0,\sigma^2/\lambda\big)"]),
   (r"Pembakuan dan intersep",
    [r"Penalti ridge bergantung pada skala prediktor: prediktor dalam gram akan disusutkan berbeda dengan prediktor yang sama dalam kilogram. Karena itu prediktor dibakukan (rata-rata nol, simpangan baku satu) sebelum ditaksir, lalu koefisien dikembalikan ke skala asli. Intersep tidak diberi penalti; dengan data terpusat intersep sama dengan rata-rata \(y\)."],
    []),
   (r"Jejak ridge dan teorema keberadaan",
    [r"Jejak ridge (ridge trace) memplot koefisien terhadap \(\lambda\). Koefisien yang berubah tajam dan berganti tanda pada \(\lambda\) kecil menandakan ketidakstabilan akibat kolinearitas. Hoerl dan Kennard membuktikan bahwa selalu ada \(\lambda>0\) yang memberi galat kuadrat rata-rata total lebih kecil daripada OLS, walaupun \(\lambda\) itu bergantung pada parameter yang tidak diketahui; dalam praktik \(\lambda\) dipilih dengan validasi silang atau GCV."],
    [r"\exists\,\lambda>0:\ E\|\hat{\boldsymbol{\beta}}^{R}(\lambda)-\boldsymbol{\beta}\|^2<E\|\hat{\boldsymbol{\beta}}^{OLS}-\boldsymbol{\beta}\|^2"])],
  [(r"Nilai singular dua arah 5 dan 0,5, dengan \(\lambda=1\). Hitung faktor penyusutan masing-masing.",
    r"\(25/26=0{,}96\) dan \(0{,}25/1{,}25=0{,}20\): arah lemah disusutkan jauh lebih kuat."),
   (r"Mengapa prediktor harus dibakukan sebelum ridge?",
    r"Karena penalti \(\sum\beta_j^2\) bergantung pada skala; tanpa pembakuan, prediktor yang satuannya kecil (koefisien besar) disusutkan lebih kuat secara sembarang."),
   (r"Apa tafsir Bayes dari \(\lambda\) yang sangat besar?",
    r"Sebaran awal normal dengan ragam sangat kecil di sekitar nol: keyakinan kuat bahwa semua koefisien hampir nol, sehingga taksiran ditarik ke nol."),
   (r"Apakah ridge dapat membuat koefisien tepat nol?",
    r"Tidak; ridge menyusutkan mendekati nol tetapi tidak tepat nol, sehingga tidak melakukan seleksi variabel. Untuk itu dipakai LASSO atau elastic net."),
   (r"Jejak ridge menunjukkan koefisien \(X_1\) turun dari 0,9 ke 0,4 dan stabil setelah \(\lambda=0{,}2\). Apa artinya?",
    r"Taksiran OLS untuk \(X_1\) tidak stabil karena kolinearitas; nilai sekitar 0,4 lebih dapat dipercaya dan \(\lambda\) sekitar 0,2 adalah kandidat yang wajar, yang dapat dikonfirmasi dengan validasi silang.")],
  [R_HK70, R_HTF, R_MPV, R_ISLR],
  contoh2=dict(judul="Contoh hitung kedua: ridge pada dua prediktor yang sangat berkorelasi",
               soal="Dua prediktor baku berkorelasi r₁₂ = 0,95, dengan korelasi terhadap respon r₁y = 0,80 dan r₂y = 0,78. Hitung koefisien OLS baku dan ridge untuk beberapa λ.",
               data=[["λ", "β₁", "β₂"], ["0 (OLS)", "0,605", "0,205"], ["0,1", "0,452", "0,319"], ["0,5", "0,341", "0,304"], ["1,0", "0,277", "0,258"]],
               langkah=[("Faktor inflasi ragam menunjukkan kolinearitas berat.", r"VIF=\frac{1}{1-0{,}95^2}=10{,}3"),
                        ("Koefisien OLS baku dari matriks korelasi.", r"\hat{\boldsymbol{\beta}}=\mathbf{R}^{-1}\mathbf{r}=\begin{pmatrix}1&0{,}95\\0{,}95&1\end{pmatrix}^{-1}\begin{pmatrix}0{,}80\\0{,}78\end{pmatrix}=\begin{pmatrix}0{,}605\\0{,}205\end{pmatrix}"),
                        ("Koefisien ridge.", r"\hat{\boldsymbol{\beta}}^{R}(\lambda)=(\mathbf{R}+\lambda\mathbf{I})^{-1}\mathbf{r},\qquad \lambda=0{,}1:\ (0{,}452;\ 0{,}319)")],
               simpul="Walaupun kedua prediktor hampir sama korelasinya dengan respon (0,80 dan 0,78), OLS memberi bobot sangat timpang (0,61 dan 0,21) karena kolinearitas. Ridge dengan λ kecil sudah menyeimbangkan keduanya ke nilai yang lebih masuk akal dan stabil."))

# ---------------------------------------------------------------- LASSO
L("regresi-lasso",
  [(r"Geometri penalti L1",
    [r"LASSO meminimumkan jumlah kuadrat galat dengan kendala \(\sum|\beta_j|\le s\). Daerah kendala L1 berbentuk belah ketupat (berlian) yang bersudut tepat di sumbu. Kontur jumlah kuadrat galat yang berbentuk elips paling sering pertama kali menyentuh daerah itu di salah satu sudut, tempat sebagian koefisien tepat nol. Daerah kendala ridge berbentuk lingkaran tanpa sudut, sehingga jarang menghasilkan nol tepat."],
    [r"\min\ \|\mathbf{y}-\mathbf{X}\boldsymbol{\beta}\|^2\ \ \text{dengan}\ \sum_j|\beta_j|\le s\quad(\text{LASSO})\qquad \text{vs}\qquad \sum_j\beta_j^2\le s\quad(\text{ridge})"]),
   (r"Syarat optimalitas",
    [r"Karena \(|\beta|\) tidak dapat diturunkan di nol, syarat optimum memakai subgradien. Pada solusi, setiap koefisien tak nol memenuhi korelasi residual dengan prediktor sama dengan \(\lambda\) bertanda sama, sedangkan koefisien nol memenuhi korelasi residual paling besar \(\lambda\) secara mutlak. Dari sini diperoleh \(\lambda_{\max}\): nilai terkecil yang membuat semua koefisien nol."],
    [r"\frac{1}{n}\mathbf{x}_j^\top(\mathbf{y}-\mathbf{X}\hat{\boldsymbol{\beta}})=\lambda\operatorname{sign}(\hat{\beta}_j)\ \ (\hat{\beta}_j\ne0),\qquad \Big|\frac{1}{n}\mathbf{x}_j^\top(\mathbf{y}-\mathbf{X}\hat{\boldsymbol{\beta}})\Big|\le\lambda\ \ (\hat{\beta}_j=0)"]),
   (r"Keterbatasan dan perbaikan",
    [r"LASSO memilih paling banyak \(n\) variabel bila \(p>n\), dan dari sekelompok variabel yang sangat berkorelasi cenderung memilih satu secara agak sembarang. Koefisien yang terpilih juga bias ke nol. Perbaikannya: LASSO adaptif (penalti berbobot \(1/|\hat{\beta}^{OLS}_j|\)) yang punya sifat oracle, relaxed LASSO (menaksir ulang tanpa penalti pada variabel terpilih), dan elastic net untuk variabel berkelompok."],
    [r"\text{LASSO adaptif}:\ \lambda\sum_j\hat{w}_j|\beta_j|,\qquad \hat{w}_j=\frac{1}{|\hat{\beta}^{OLS}_j|^{\gamma}}"]),
   (r"Memilih λ dan inferensi",
    [r"\(\lambda\) dipilih dengan validasi silang; aturan satu galat baku memilih \(\lambda\) terbesar yang galat validasi silangnya masih dalam satu galat baku dari minimum, menghasilkan model lebih sederhana dengan kinerja hampir sama. Galat baku dan P-value biasa tidak berlaku setelah seleksi oleh LASSO; inferensi pasca-seleksi memerlukan metode khusus atau pembagian data (satu bagian untuk memilih, bagian lain untuk menguji)."],
    [])],
  [(r"Dengan desain ortonormal, koefisien OLS 1,8 dan −0,6, dan \(\lambda=0{,}8\). Hitung koefisien LASSO.",
    r"\(S(1{,}8;0{,}8)=1{,}0\) dan \(S(-0{,}6;0{,}8)=0\): koefisien kedua menjadi tepat nol."),
   (r"Mengapa LASSO bisa menghasilkan koefisien tepat nol, sedangkan ridge tidak?",
    r"Daerah kendala L1 bersudut di sumbu, sehingga solusi sering jatuh di sudut tempat sebagian koefisien nol; daerah kendala L2 berbentuk bulat tanpa sudut."),
   (r"Dua prediktor hampir identik (korelasi 0,99) sama-sama berhubungan dengan respon. Apa yang cenderung dilakukan LASSO?",
    r"Memilih salah satu dan membuang yang lain secara agak sembarang; elastic net cenderung mempertahankan keduanya dengan koefisien serupa."),
   (r"Apa itu aturan satu galat baku pada pemilihan \(\lambda\)?",
    r"Memilih \(\lambda\) terbesar yang galat validasi silangnya masih dalam satu galat baku dari galat minimum, sehingga model lebih sederhana dengan kinerja hampir setara."),
   (r"Bolehkah P-value dari OLS pada variabel yang dipilih LASSO dilaporkan apa adanya?",
    r"Tidak; seleksi memakai data yang sama, sehingga P-value terlalu optimistis. Gunakan metode inferensi pasca-seleksi atau pisahkan data seleksi dan data uji.")],
  [R_TIB96, R_HTF, R_ISLR],
  contoh2=dict(judul="Contoh hitung kedua: LASSO dan ridge pada desain ortonormal",
               soal="Pada desain ortonormal, koefisien OLS baku empat prediktor adalah 2,5; −0,8; 0,3; dan 1,6. Bandingkan LASSO dan ridge dengan λ = 1.",
               data=[["Prediktor", "OLS", "LASSO (λ = 1)", "Ridge (λ = 1)"], ["x1", "2,5", "1,5", "1,25"], ["x2", "−0,8", "0", "−0,40"], ["x3", "0,3", "0", "0,15"], ["x4", "1,6", "0,6", "0,80"]],
               langkah=[("LASSO: soft-thresholding, kurangi |b| sebesar λ dan nolkan bila negatif.", r"\hat{\beta}^{L}_j=\operatorname{sign}(b_j)\big(|b_j|-1\big)_+:\quad 1{,}5;\ 0;\ 0;\ 0{,}6"),
                        ("Ridge: semua koefisien dikalikan faktor yang sama.", r"\hat{\beta}^{R}_j=\frac{b_j}{1+\lambda}=\frac{b_j}{2}:\quad 1{,}25;\ -0{,}40;\ 0{,}15;\ 0{,}80"),
                        ("Bandingkan pola penyusutan.", r"\text{LASSO: geser tetap }\lambda;\qquad \text{ridge: skala tetap }\tfrac{1}{1+\lambda}")],
               simpul="LASSO membuang x2 dan x3 sepenuhnya dan menggeser koefisien besar sebesar λ yang sama; ridge mempertahankan keempat variabel dengan menyusutkan semuanya secara proporsional. Karena itu LASSO melakukan seleksi variabel, ridge tidak."))

# ---------------------------------------------------------------- elastic net
L("elastic-net",
  [(r"Mengapa menggabungkan L1 dan L2",
    [r"Elastic net mewarisi seleksi variabel dari LASSO (bagian L1) dan kestabilan serta efek pengelompokan dari ridge (bagian L2). Bagian L2 membuat fungsi tujuan konveks tegas, sehingga solusinya unik walaupun prediktor sangat berkorelasi atau \(p>n\), dan elastic net dapat memilih lebih dari \(n\) variabel."],
    []),
   (r"Efek pengelompokan",
    [r"Zou dan Hastie menunjukkan bahwa selisih koefisien elastic net untuk dua prediktor baku dibatasi oleh korelasinya: makin tinggi korelasi, makin mirip koefisiennya. Akibatnya kelompok prediktor yang sangat berkorelasi cenderung masuk atau keluar bersama, sifat yang penting misalnya pada data gen atau spektrum yang datang berkelompok."],
    [r"\frac{|\hat{\beta}_i-\hat{\beta}_j|}{\|\mathbf{y}\|_1}\le\frac{1}{\lambda(1-\alpha)}\sqrt{2(1-\rho_{ij})}"]),
   (r"Elastic net naif dan koreksi skala",
    [r"Versi awal (naif) menyusutkan dua kali, oleh bagian L1 dan L2, sehingga koefisien terlalu kecil. Zou dan Hastie mengusulkan mengalikan hasil dengan \((1+\lambda_2)\) untuk membatalkan penyusutan ganda. Implementasi modern seperti glmnet memakai parameterisasi \(\lambda,\alpha\) tanpa koreksi itu, sehingga koefisien antar perangkat lunak dapat berbeda skala; periksa definisi yang dipakai."],
    [r"\hat{\boldsymbol{\beta}}_{EN}=(1+\lambda_2)\,\hat{\boldsymbol{\beta}}_{\text{naif}}"]),
   (r"Memilih α dan λ",
    [r"Dua parameter dipilih bersama dengan validasi silang pada kisi: beberapa nilai \(\alpha\) (misalnya 0; 0,25; 0,5; 0,75; 1), dan untuk setiap \(\alpha\) seluruh jalur \(\lambda\). Gunakan pembagian lipatan yang sama untuk semua \(\alpha\) agar perbandingannya adil. \(\alpha\) mendekati 1 bila diharapkan sedikit variabel aktif; \(\alpha\) kecil bila banyak variabel kecil yang berkorelasi."],
    [])],
  [(r"Desain ortonormal, koefisien OLS 2,0, \(\lambda=1\), \(\alpha=0{,}5\). Hitung koefisien elastic net.",
    r"\(S(2{,}0;0{,}5)/(1+0{,}5)=1{,}5/1{,}5=1{,}0\)."),
   (r"Elastic net dengan \(\alpha=1\) dan \(\alpha=0\) setara dengan apa?",
    r"\(\alpha=1\): LASSO. \(\alpha=0\): ridge."),
   (r"Mengapa elastic net dapat memilih lebih dari \(n\) variabel, sedangkan LASSO tidak?",
    r"Karena bagian L2 membuat masalah konveks tegas dan setara dengan LASSO pada data yang diperluas dengan \(p\) baris tambahan, sehingga batas \(n\) variabel tidak berlaku."),
   (r"Tiga prediktor spektrum berkorelasi 0,98 dan semuanya relevan. Metode mana yang cenderung mempertahankan ketiganya?",
    r"Elastic net (\(\alpha<1\)), karena efek pengelompokan membuat koefisien prediktor yang sangat berkorelasi serupa dan masuk bersama."),
   (r"Mengapa koefisien elastic net dari dua perangkat lunak berbeda bisa berbeda skala?",
    r"Karena parameterisasi berbeda: sebagian memakai koreksi \((1+\lambda_2)\) dan sebagian tidak, serta skala fungsi kerugian (misalnya \(1/2n\)) yang berbeda.")],
  [R_ZH05, R_HTF, R_ISLR],
  contoh2=dict(judul="Contoh hitung kedua: elastic net pada desain ortonormal",
               soal="Koefisien OLS baku yang sama (2,5; −0,8; 0,3; 1,6) pada desain ortonormal, kini dengan elastic net λ = 1 dan α = 0,5.",
               data=[["Prediktor", "OLS", "LASSO", "Elastic net", "Ridge"], ["x1", "2,5", "1,50", "1,33", "1,25"], ["x2", "−0,8", "0", "−0,20", "−0,40"], ["x3", "0,3", "0", "0", "0,15"], ["x4", "1,6", "0,60", "0,73", "0,80"]],
               langkah=[("Ambang L1 adalah λα = 0,5.", r"S(b_j;0{,}5):\quad 2{,}0;\ -0{,}3;\ 0;\ 1{,}1"),
                        ("Bagi dengan 1 + λ(1 − α) = 1,5 untuk penyusutan L2.", r"\hat{\beta}_j=\frac{S(b_j;0{,}5)}{1{,}5}:\quad 1{,}33;\ -0{,}20;\ 0;\ 0{,}73")],
               simpul="Elastic net berada di antara LASSO dan ridge: x3 tetap dibuang (seleksi), tetapi x2 dipertahankan dengan koefisien kecil, dan koefisien besar disusutkan lebih lembut daripada LASSO."))

# ---------------------------------------------------------------- PCR
L("principal-component-regression-pcr",
  [(r"Hubungan dengan dekomposisi nilai singular",
    [r"Komponen utama adalah kombinasi linear prediktor baku dengan bobot vektor ciri matriks korelasi \(\mathbf{R}\). Komponen ke-\(j\) punya ragam \(\lambda_j\) dan tidak berkorelasi dengan komponen lain. Karena tidak berkorelasi, regresi respon pada komponen menghasilkan koefisien yang dapat ditaksir terpisah, lalu dikembalikan ke skala prediktor asli."],
    [r"\mathbf{Z}=\mathbf{X}\mathbf{V},\quad \operatorname{Var}(\mathbf{z}_j)=\lambda_j,\qquad \hat{\gamma}_j=\frac{\mathbf{v}_j^\top\mathbf{r}}{\lambda_j},\qquad \hat{\boldsymbol{\beta}}_{PCR}=\sum_{j=1}^{k}\hat{\gamma}_j\mathbf{v}_j"]),
   (r"PCR sebagai penyusutan diskret",
    [r"Bila dibandingkan dengan ridge, PCR adalah penyusutan 'semua atau tidak sama sekali': komponen dengan ragam besar dipertahankan penuh (faktor 1), komponen dengan ragam kecil dibuang (faktor 0). Ridge menyusutkan semua komponen secara halus dengan faktor \(\lambda_j/(\lambda_j+\lambda)\). Keduanya paling kuat menyusutkan arah berragam kecil, tempat kolinearitas membuat taksiran OLS tidak stabil."],
    [r"\text{PCR}:\ f_j\in\{0,1\},\qquad \text{ridge}:\ f_j=\frac{\lambda_j}{\lambda_j+\lambda}"]),
   (r"Kelemahan: komponen dipilih tanpa melihat respon",
    [r"Komponen utama disusun hanya dari prediktor, tanpa memperhatikan \(y\). Komponen berragam kecil yang dibuang bisa saja justru yang berhubungan kuat dengan respon. Karena itu jumlah komponen sebaiknya dipilih dengan validasi silang terhadap galat prediksi, bukan hanya dengan proporsi ragam prediktor yang dijelaskan. PLS mengatasi kelemahan ini dengan memakai \(y\) saat membentuk komponen."],
    []),
   (r"Tafsir dan pelaporan",
    [r"Koefisien PCR dalam skala asli bias (karena sebagian informasi dibuang) tetapi ragamnya jauh lebih kecil daripada OLS pada data yang kolinear. Laporkan banyak komponen, proporsi ragam prediktor dan respon yang dijelaskan, serta kriteria pemilihannya. Muatan (loading) komponen dapat ditafsirkan bila polanya jelas, misalnya komponen pertama sebagai 'ukuran umum'."],
    [])],
  [(r"Matriks korelasi dua prediktor dengan \(r=0{,}8\). Hitung kedua akar ciri dan proporsi ragam komponen pertama.",
    r"\(\lambda_1=1{,}8\), \(\lambda_2=0{,}2\). Komponen pertama menjelaskan \(1{,}8/2=90\%\) ragam prediktor."),
   (r"Mengapa PCR dapat membuang komponen yang justru penting bagi respon?",
    r"Karena komponen disusun dan diurutkan hanya menurut ragam prediktor, tanpa melihat hubungannya dengan \(y\)."),
   (r"Bandingkan faktor penyusutan ridge (\(\lambda=0{,}2\)) dan PCR (1 komponen) untuk akar ciri 1,8 dan 0,2.",
    r"Ridge: \(1{,}8/2{,}0=0{,}90\) dan \(0{,}2/0{,}4=0{,}50\). PCR: 1 dan 0."),
   (r"Dengan semua \(p\) komponen dipakai, PCR setara dengan apa?",
    r"Dengan OLS biasa, karena tidak ada informasi yang dibuang."),
   (r"Bagaimana memilih banyak komponen secara tepat?",
    r"Dengan validasi silang (misalnya 10-lipat) terhadap galat prediksi respon, sering dengan aturan satu galat baku.")],
  [R_JOL, R_HTF, R_ISLR, R_MPV],
  contoh2=dict(judul="Contoh hitung kedua: PCR dengan dua prediktor kolinear",
               soal="Dua prediktor baku berkorelasi 0,9; korelasinya dengan respon 0,8 dan 0,7. Bandingkan OLS dan PCR dengan satu komponen.",
               data=None,
               langkah=[("Akar ciri dan vektor ciri matriks korelasi.", r"\lambda_1=1{,}9,\ \mathbf{v}_1=\tfrac{1}{\sqrt2}(1,1);\qquad \lambda_2=0{,}1,\ \mathbf{v}_2=\tfrac{1}{\sqrt2}(1,-1)"),
                        ("Koefisien OLS baku (perhatikan tanda negatif yang aneh).", r"\hat{\boldsymbol{\beta}}_{OLS}=\mathbf{R}^{-1}\mathbf{r}=(0{,}895;\ -0{,}105),\qquad R^2=0{,}642"),
                        ("Koefisien pada komponen pertama.", r"\hat{\gamma}_1=\frac{\mathbf{v}_1^\top\mathbf{r}}{\lambda_1}=\frac{1{,}061}{1{,}9}=0{,}558"),
                        ("Kembalikan ke skala prediktor.", r"\hat{\boldsymbol{\beta}}_{PCR}=0{,}558\,\mathbf{v}_1=(0{,}395;\ 0{,}395),\qquad R^2=0{,}592")],
               simpul="OLS memberi X2 koefisien negatif walaupun X2 berkorelasi positif dengan respon, akibat kolinearitas. PCR dengan satu komponen memberi koefisien positif yang sama untuk keduanya dan hanya kehilangan 5 poin R² (0,642 menjadi 0,592), dengan taksiran yang jauh lebih stabil."))

# ---------------------------------------------------------------- PLS
L("partial-least-squares-pls",
  [(r"Kriteria pembentukan komponen",
    [r"PLS memilih arah bobot \(\mathbf{w}\) yang memaksimumkan kovarians antara skor komponen \(\mathbf{t}=\mathbf{X}\mathbf{w}\) dan respon, bukan ragam \(\mathbf{t}\) seperti PCA. Kovarians adalah hasil kali korelasi dan simpangan baku, sehingga PLS mencari kompromi: arah yang cukup beragam dan cukup berhubungan dengan \(y\). Untuk satu respon, bobot komponen pertama sebanding dengan \(\mathbf{X}^\top\mathbf{y}\)."],
    [r"\mathbf{w}_1=\arg\max_{\|\mathbf{w}\|=1}\operatorname{Cov}(\mathbf{X}\mathbf{w},\mathbf{y})^2\ \Rightarrow\ \mathbf{w}_1\propto\mathbf{X}^\top\mathbf{y}"]),
   (r"Komponen berikutnya dan deflasi",
    [r"Setelah komponen pertama ditaksir, \(\mathbf{X}\) dan \(\mathbf{y}\) dikurangi bagian yang sudah dijelaskan (deflasi), lalu kriteria yang sama diterapkan pada sisanya. Komponen PLS saling tidak berkorelasi. Dengan semua komponen dipakai, PLS setara dengan OLS; dengan sedikit komponen, PLS adalah bentuk penyusutan yang biasanya mencapai galat prediksi rendah dengan lebih sedikit komponen daripada PCR."],
    [r"\mathbf{X}_{(2)}=\mathbf{X}-\mathbf{t}_1\mathbf{p}_1^\top,\qquad \mathbf{p}_1=\frac{\mathbf{X}^\top\mathbf{t}_1}{\mathbf{t}_1^\top\mathbf{t}_1}"]),
   (r"VIP: pentingnya variabel",
    [r"Skor VIP (variable importance in projection) meringkas kontribusi setiap prediktor ke semua komponen, ditimbang dengan ragam \(y\) yang dijelaskan tiap komponen. Rata-rata kuadrat VIP sama dengan 1, sehingga pedoman praktis menganggap prediktor dengan VIP di atas 1 penting dan di bawah sekitar 0,8 kurang penting."],
    [r"VIP_j=\sqrt{p\,\frac{\sum_a SS_a\,(w_{ja}/\|\mathbf{w}_a\|)^2}{\sum_a SS_a}}"]),
   (r"Pemakaian khas",
    [r"PLS banyak dipakai pada kemometrika (spektrum NIR dengan ratusan panjang gelombang untuk memprediksi kadar), sensorik, dan data dengan prediktor jauh lebih banyak daripada pengamatan. Untuk banyak respon sekaligus dipakai PLS2. Validasi silang wajib untuk menentukan banyak komponen, karena PLS mudah overfit bila komponen terlalu banyak."],
    [])],
  [(r"Untuk satu respon, mengapa bobot komponen PLS pertama sebanding dengan \(\mathbf{X}^\top\mathbf{y}\)?",
    r"Karena kovarians \(\mathbf{w}^\top\mathbf{X}^\top\mathbf{y}\) dengan kendala \(\|\mathbf{w}\|=1\) maksimum bila \(\mathbf{w}\) searah dengan \(\mathbf{X}^\top\mathbf{y}\) (ketaksamaan Cauchy–Schwarz)."),
   (r"Apa perbedaan utama komponen PLS dan komponen utama?",
    r"Komponen utama memaksimumkan ragam prediktor tanpa melihat respon; komponen PLS memaksimumkan kovarians dengan respon."),
   (r"Sebuah prediktor punya VIP 0,6. Bagaimana menafsirkannya?",
    r"Kontribusinya pada model PLS kecil (di bawah pedoman sekitar 0,8), sehingga kandidat untuk dibuang bila model ingin disederhanakan."),
   (r"Data spektrum dengan 500 panjang gelombang dan 60 sampel. Mengapa OLS tidak dapat dipakai dan PLS dapat?",
    r"OLS memerlukan \(\mathbf{X}^\top\mathbf{X}\) dapat dibalik, yang tidak mungkin bila \(p>n\). PLS hanya menaksir beberapa komponen, sehingga tetap dapat dihitung."),
   (r"Bagaimana menghindari overfit pada PLS?",
    r"Pilih banyak komponen dengan validasi silang dan uji model pada data yang tidak dipakai untuk menaksir.")],
  [R_WOLD, R_HTF, R_ISLR],
  contoh2=dict(judul="Contoh hitung kedua: PLS satu komponen dibanding PCR",
               soal="Dua prediktor baku yang sama (korelasi 0,9; korelasi dengan respon 0,8 dan 0,7). Hitung PLS satu komponen dan bandingkan dengan PCR satu komponen.",
               data=None,
               langkah=[("Bobot PLS sebanding dengan korelasi prediktor terhadap respon.", r"\mathbf{w}_1=\frac{(0{,}8;\ 0{,}7)}{\|(0{,}8;\ 0{,}7)\|}=(0{,}753;\ 0{,}659)"),
                        ("Koefisien respon atas skor komponen.", r"c=\frac{\mathbf{w}_1^\top\mathbf{r}}{\mathbf{w}_1^\top\mathbf{R}\mathbf{w}_1}=\frac{1{,}063}{1{,}892}=0{,}562"),
                        ("Koefisien dalam skala prediktor dan R².", r"\hat{\boldsymbol{\beta}}_{PLS}=c\,\mathbf{w}_1=(0{,}423;\ 0{,}370),\qquad R^2=0{,}597"),
                        ("Bandingkan dengan PCR satu komponen dan OLS.", r"R^2_{PCR}=0{,}592,\qquad R^2_{OLS}=0{,}642")],
               simpul="Dengan satu komponen, PLS menjelaskan sedikit lebih banyak keragaman respon daripada PCR (0,597 lawan 0,592) karena arahnya ikut ditentukan respon, dan memberi X1 bobot sedikit lebih besar sesuai korelasinya yang lebih tinggi dengan respon."))
